(window.webpackJsonp=window.webpackJsonp||[]).push([[22],{409:function(e,t,v){"use strict";v.r(t);var n=v(11),r=Object(n.a)({},(function(){var e=this,t=e._self._c;return t("ContentSlotsDistributor",{attrs:{"slot-key":e.$parent.slotKey}},[t("p",[e._v("读博的日子真的过得很快，四年的光阴不过弹指一挥间。周围认识的人相继毕业，我已经成了UIUC名副其实的老登。香槟这个地方呆久了，会恍惚自己进入了一个结界，结界里的活动只有research，每天两点一线，家--siebel 或者 siebel--家。emo的情绪就像潮水，每天潮起潮落，连绵不绝。但好在潮水上不了岸，也不会彻底冲垮精神世界。")]),e._v(" "),t("p",[e._v("老登的特点之一就是喜欢回首过去。再次翻看我入学之前看到的劝退帖，《"),t("a",{attrs:{href:"https://movie.douban.com/review/6180006/",target:"_blank",rel:"noopener noreferrer"}},[e._v("魔法少女小圆其实讲的是PhD的故事"),t("OutboundLink")],1),e._v("》，真是别有一番滋味。可能是初生牛犊不怕虎吧。这种明知山有虎，偏向虎山行的英勇精神还蛮让现在的我佩服的。我很难斗志昂扬，精神抖擞地说，再来一次还会毫不犹豫选择这条路。但我能说的是，我会在斟酌再三，反复犹疑之后，再次踏上这条布满荆棘的征程。")]),e._v(" "),t("p",[e._v("读博最痛苦，挑战最大的地方不是体力上的痛苦，而是精神上的凌迟。我不想美化这条路，我也不想假装自己是天赋型选手，举重若轻。我的经历就是，我做了很多很多实验，绝大多数都是失败。不停地迭代，看不到尽头在哪里。我其实不怕累的，只是这种盲人点灯的经历很让人绝望。从去年五月开始到十一月一直在推一个项目，半年时间最后证明motivation就是错的。但这就是科研，它不会因为你花的时间多，就给你苦劳，假装错的是对的。")]),e._v(" "),t("p",[e._v("这一次我很快就接受了这个结果，自悯自怜毫无意义。让我蛮感动的是，老板怕我心态爆炸，还特意在他开会的间隙来找我闲聊，估计是怕我再次陷入悲观情绪。怎么说呢，肯定是会有情绪波澜的。但失败这件事，就和练举重一样，刚开始一点重量就会将你击垮，但后面练的多了，你的肌肉在反复拉扯后，会变得越来越强大。")]),e._v(" "),t("p",[e._v("失败之后，重要的如何把错误纠正，而不是抱怨为什么这件事会发生我身上。这估计也是读博最大的财富吧。读博这个选择，可以给你五年时光，没有外在压力，自由地去探索一些未知的问题。就算探索失败，最直接的代价也不过是少了一篇论文，而不是人生就此崩塌。")]),e._v(" "),t("p",[e._v("想明白这一点其实就好受很多了。只要稳住自己的心态，不要在意外界的看法，后面的事都好说。把读博当作一个给你失败权利的机会。五年时间，总会做出来满意的成果的。")]),e._v(" "),t("p",[e._v("产出是需要时间的。如果想要做出一个完善的工作，前期那些看起来漫长、混乱、没有结果的探索，或许本来就是必要的一部分。所以现在再看到那些“两周发一篇论文”“三天从零完成一个项目”的内容，我内心毫无波澜。如果只看最后出成果的那一刻，那我甚至也可以说，我只花了一天就申请到了 PhD。")]),e._v(" "),t("p",[e._v("科研不是短视频，无法每一步都即时反馈，也很难每一次努力都立刻兑换成成果。很多时候，我们能做的只是判断一个方向还值得走，然后在漫长的不确定里继续走下去。")]),e._v(" "),t("p",[e._v("如果我们能确信自己做的是正确的事，那只要继续走下去就好。同祝。")])])}),[],!1,null,null,null);t.default=r.exports}}]);